<script setup lang="ts">
import {canTeach} from '../course-access';import type {Course} from '../models';import {computed,ref,watch} from 'vue';import {useRoute} from 'vue-router';import {api} from '../api';import {session} from '../session';import {useTask,time} from '../useTask';import {csv,download} from '../export';import PageHeading from '../components/PageHeading.vue';import StatePanel from '../components/StatePanel.vue';
interface Item {kind:string;id:string;title:string;status:string;percent:string|null}
interface Row {studentId:string;displayName:string;assignment:string|null;practice:string|null;provisional:string|null;total:string|null;pending:number;missing:number;items:Item[]}
interface Book {courseId:string;policy:{assignmentWeight:number;practiceWeight:number;missingRule:string;attemptRule:string;version:number};students:Row[];calculatedAt:string}
const route=useRoute(),id=computed(()=>String(route.params.courseId)),teacher=computed(()=>session.value?.user.role==='TEACHER'),course=ref<Course|null>(null),book=ref<Book|null>(null),selected=ref<Row|null>(null),policy=ref({assignmentWeight:70,missingRule:'EXCLUDE',attemptRule:'HIGHEST',version:-1});const {busy,error,run}=useTask();
const labels:Record<string,string>={GRADED:'已有成绩',PENDING:'待评分',OPEN:'待完成',MISSING:'截止后缺交'};
function load(){run(async()=>{course.value=await api<Course>('/api/courses/'+id.value);book.value=await api<Book>('/api/grades/courses/'+id.value);policy.value={...book.value.policy};selected.value=teacher.value?null:book.value.students[0]||null;});}
watch(id,load,{immediate:true});
function save(){run(async()=>{await api('/api/grades/courses/'+id.value+'/policy',{method:'PUT',body:{assignmentWeight:policy.value.assignmentWeight,missingRule:policy.value.missingRule,attemptRule:policy.value.attemptRule,expectedVersion:policy.value.version}});book.value=await api<Book>('/api/grades/courses/'+id.value);policy.value={...book.value.policy};selected.value=teacher.value?null:book.value.students[0]||null;});}
function exportBook(){if(!book.value)return;const b=book.value;download(csv([['学生编号','学生','作业权重','测验取值','缺交规则','作业均分率','练习均分率','当前参考值','课程总评','待完成/待批阅项','截止后缺交项','计算时间'],...b.students.map(s=>[s.studentId,s.displayName,b.policy.assignmentWeight,b.policy.attemptRule,b.policy.missingRule,s.assignment??'暂无',s.practice??'暂无',s.provisional??'暂无',s.total??'未结算',s.pending,s.missing,b.calculatedAt])]),'课程成绩册.csv','text/csv;charset=utf-8');}
</script>
<template><PageHeading title="课程成绩册" :back="teacher?'/teacher/courses/'+id+'/analytics':'/student/courses/'+id" description="逐项核对得分，再查看课程总评。"><el-button v-if="book" @click="exportBook">导出成绩册</el-button></PageHeading><StatePanel :busy="busy&&!book" :error="error" @retry="load"/>
<template v-if="book"><section class="paper grade-policy"><h2>总评口径</h2><p>作业 {{book.policy.assignmentWeight}}% · 练习 {{book.policy.practiceWeight}}%。每项先折算为百分制，再分别平均。练习取{{book.policy.attemptRule==='HIGHEST'?'最高得分率':'最近一次提交'}}；截止后缺交{{book.policy.missingRule==='ZERO'?'按零分纳入平均':'从平均中排除'}}。</p><p class="field-hint">待批阅、尚未截止的未完成项保持未知；必计类别没有成绩时，总评不结算。参考值只基于已有成绩。计算于 {{time(book.calculatedAt)}}。</p>
<form v-if="teacher&&canTeach(course)&&course?.status==='PUBLISHED'" class="toolbar" @submit.prevent="save"><label>作业权重<el-input-number v-model="policy.assignmentWeight" :min="0" :max="100" aria-label="作业权重"/></label><label>缺交处理<el-select v-model="policy.missingRule" aria-label="缺交处理"><el-option label="排除缺交项" value="EXCLUDE"/><el-option label="截止后按零分" value="ZERO"/></el-select></label><label>重试成绩<el-select v-model="policy.attemptRule" aria-label="重试成绩"><el-option label="最高得分率" value="HIGHEST"/><el-option label="最近一次" value="LATEST"/></el-select></label><el-button type="primary" native-type="submit" :loading="busy">保存规则</el-button></form></section>
<section class="paper"><el-table :data="book.students" empty-text="暂无选课学生"><el-table-column prop="displayName" label="学生" min-width="140"/><el-table-column label="作业均分率" min-width="110"><template #default="{row}">{{row.assignment??'暂无'}}</template></el-table-column><el-table-column label="练习均分率" min-width="110"><template #default="{row}">{{row.practice??'暂无'}}</template></el-table-column><el-table-column label="课程总评" min-width="130"><template #default="{row}"><strong>{{row.total??'未结算'}}</strong><small v-if="row.total===null&&row.provisional!==null" class="field-hint">参考 {{row.provisional}}</small></template></el-table-column><el-table-column prop="pending" label="待完成/待批阅" min-width="120"/><el-table-column prop="missing" label="缺交" width="70"/><el-table-column label="明细" width="80"><template #default="{row}"><el-button @click="selected=row">展开</el-button></template></el-table-column></el-table></section>
<section v-if="selected" class="paper grade-details"><h2>{{selected.displayName}}的逐项成绩</h2><ul><li v-for="i in selected.items" :key="i.kind+i.id"><span>{{i.kind==='ASSIGNMENT'?'习作':'练习'}} · {{i.title}}</span><span>{{labels[i.status]}} <strong>{{i.percent===null?'—':Number(i.percent).toFixed(2)+'%'}}</strong></span></li></ul><p v-if="!selected.items.length">尚无公开的作业或测验。</p></section></template>
</template>
